+// Shortcuts that make work look done. They are flags for the user, not refusals: the run's own changes are
+// read from the snapshot patch (or the edit and write calls) and each added line is matched.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const TEST_PATH = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/)/;
+const PROSE = /\.(md|mdx|txt|rst)$/;
+const ASSERT = /\bexpect\(|\bassert/;
+const SKIP = /\.skip\(|\bxit\(|\bxdescribe\(|\bt\.Skip\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const SUPPRESS = /@ts-(ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|# pylint: disable|nolint/;
+const EMPTY_CATCH = /catch\s*(\([^)]*\))?\s*\{\s*\}/;
+const PY_SWALLOW = /^\s*except\b.*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b/;
+const STUB = /\bNotImplementedError\b|not implemented['"]\)|\btodo!\(\)|\bunimplemented!\(\)/i;
+
+// Reads a `git diff -U0` patch: one FileChange per file, with the added and removed lines of its hunks.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHeader = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      cur = { path: line.slice(line.indexOf(' b/') + 3), added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHeader = true;
+    } else if (!cur) {
+      continue;
+    } else if (line.startsWith('@@')) {
+      inHeader = false;
+    } else if (inHeader) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) {
+      cur.added.push(line.slice(1));
+    } else if (line.startsWith('-')) {
+      cur.removed.push(line.slice(1));
+    }
+  }
+  return out;
+}
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    if (PROSE.test(c.path)) continue;
+    const isTest = TEST_PATH.test(c.path);
+    if (isTest && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (isTest && !c.deleted && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    for (const line of c.added) {
+      const hit = (rule: string) => out.push({ rule, path: c.path, line: line.trim() });
+      if (isTest && SKIP.test(line)) hit('test-skipped');
+      if (SUPPRESS.test(line)) hit('suppression');
+      if (EMPTY_CATCH.test(line) || PY_SWALLOW.test(line)) hit('swallowed-error');
+      if (TYPE_ESCAPE.test(line)) hit('type-escape');
+      if (STUB.test(line)) hit('stub');
+    }
+  }
+  return out;
+}
+
+export const slopLabel = (f: SlopFinding) => (f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
+
+// Without snapshots, the changes are what the edit and write calls asked for. A write's old content is not known.
+export function changesFromCalls(calls: { tool: string; input: Record<string, unknown> }[]): FileChange[] {
+  return calls.flatMap(({ tool, input }): FileChange[] => {
+    const path = String(input.path ?? '');
+    if (tool === 'write') return [{ path, added: String(input.content ?? '').split('\n'), removed: [], deleted: false }];
+    if (tool === 'edit') return [{ path, added: String(input.new_text ?? '').split('\n'), removed: String(input.old_text ?? '').split('\n'), deleted: false }];
+    return [];
+  });
+}
