+// Shortcuts that make work look done. They are flags for the reader, not refusals: a run may keep them with a reason.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const TEST_FILE = /(^|\/)(tests?\/|[^/]*\.(test|spec)\.[^/]*$|[^/]*_test\.[^/]*$|test_[^/]*$)/;
+const DOC_FILE = /\.(md|mdx|txt|rst)$/;
+const ASSERT = /\bexpect\(|\bassert\b|\bassert[A-Z]\w*\(|\.to[A-Z]\w*\(|\bt\.(Error|Errorf|Fatal|Fatalf)\(/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bxit\(|\bxdescribe\(|\bt\.Skip(Now)?\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const SUPPRESSION = /@ts-ignore|@ts-nocheck|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/\s*nolint/;
+const SWALLOWED = /catch\s*(\([^)]*\))?\s*\{\s*\}|except\b[^:]*:\s*pass\b/;
+const TYPE_ESCAPE = /\bas any\b|<any>/;
+const STUB = /NotImplementedError|throw new Error\(\s*['"`]not implemented/i;
+
+const countAsserts = (lines: string[]) => lines.filter((l) => ASSERT.test(l)).length;
+
+// Reads a `git diff -U0` patch into per-file added and removed lines.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      const m = /^diff --git a\/.* b\/(.*)$/.exec(line);
+      cur = { path: m?.[1] ?? line, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) {
+      continue;
+    } else if (line.startsWith('deleted file mode')) {
+      cur.deleted = true;
+    } else if (line.startsWith('@@')) {
+      inHunk = true;
+    } else if (inHunk && line.startsWith('+')) {
+      cur.added.push(line.slice(1));
+    } else if (inHunk && line.startsWith('-')) {
+      cur.removed.push(line.slice(1));
+    }
+  }
+  return out;
+}
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_FILE.test(c.path);
+    if (isTest && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (isTest && !c.deleted && countAsserts(c.removed) > countAsserts(c.added)) out.push({ rule: 'test-weakened', path: c.path });
+    if (DOC_FILE.test(c.path)) continue;
+    for (const raw of c.added) {
+      const line = raw.trim();
+      const hit = (rule: string) => out.push({ rule, path: c.path, line });
+      if (isTest && SKIP.test(line)) hit('test-skipped');
+      if (SUPPRESSION.test(line)) hit('suppression');
+      if (SWALLOWED.test(line)) hit('swallowed-error');
+      if (TYPE_ESCAPE.test(line)) hit('type-escape');
+      if (STUB.test(line)) hit('stub');
+    }
+  }
+  return out;
+}
+
+export const flagText = (f: SlopFinding) => `${f.rule} ${f.path}${f.line ? `: ${f.line}` : ''}`;
